1	// Telas do Maxx.
2	const { html, raw } = require('./html');
3	const config = require('./config');
4	const { CONTAS: CONTAS_BANCA } = require('./banca');
5	const { PONTOS, CONQUISTAS } = require('./regras');
6	
7	// ---------- Ícones ----------
8	const svg = (corpo) =>
9	  raw(`<svg viewBox="0 0 24 24" width="26" height="26" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${corpo}</svg>`);
10	
11	const icone = {
12	  inicio: svg('<path d="M3 10.5 12 3l9 7.5V21h-6v-6H9v6H3z"/>'),
13	  mural: svg('<path d="M3 11v2a1 1 0 0 0 1 1h3l5 4V6L7 10H4a1 1 0 0 0-1 1z"/><path d="M16 9a3 3 0 0 1 0 6"/><path d="M19 6a7 7 0 0 1 0 12"/>'),
14	  novo: svg('<rect x="3" y="3" width="18" height="18" rx="5"/><path d="M12 8v8M8 12h8"/>'),
15	  ranking: svg('<path d="M8 21h8M12 17v4M7 4h10v5a5 5 0 0 1-10 0z"/><path d="M17 5h3a3 3 0 0 1-3 4M7 5H4a3 3 0 0 0 3 4"/>'),
16	  perfil: svg('<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>'),
17	  coracao: svg('<path d="M12 20.5s-7.5-4.6-9.6-9.3A5.4 5.4 0 0 1 12 5.7a5.4 5.4 0 0 1 9.6 5.5C19.5 15.9 12 20.5 12 20.5z"/>'),
18	  comentario: svg('<path d="M21 12a8 8 0 0 1-11.6 7.1L4 20.5l1.5-5A8 8 0 1 1 21 12z"/>'),
19	};
20	
21	// ---------- Utilidades ----------
22	function tempoRelativo(dataSql) {
23	  const data = new Date(String(dataSql).replace(' ', 'T') + 'Z');
24	  const seg = Math.floor((Date.now() - data.getTime()) / 1000);
25	  if (seg < 60) return 'agora';
26	  if (seg < 3600) return `há ${Math.floor(seg / 60)} min`;
27	  if (seg < 86400) return `há ${Math.floor(seg / 3600)} h`;
28	  if (seg < 7 * 86400) return `há ${Math.floor(seg / 86400)} d`;
29	  return data.toLocaleDateString('pt-BR');
30	}
31	
32	const plural = (n, um, varios) => `${n} ${n === 1 ? um : varios}`;
33	const fmt = (n) => Number(n).toLocaleString('pt-BR');
34	
35	function avatar(u, tamanho = 'p') {
36	  if (u.avatar) return html`<img class="avatar avatar-${tamanho}" src="/uploads/${u.avatar}" alt="">`;
37	  const matiz = (Number(u.usuario_id ?? u.id) * 67) % 360;
38	  const inicial = (u.nome || '?').trim().charAt(0).toUpperCase();
39	  return html`<span class="avatar avatar-${tamanho} avatar-letra" style="--matiz:${matiz}" aria-hidden="true">${inicial}</span>`;
40	}
41	
42	function selo(papel) {
43	  if (papel === 'professor') return html`<span class="selo selo-prof">Professor(a)</span>`;
44	  if (papel === 'admin') return html`<span class="selo selo-oficial">Oficial</span>`;
45	  return '';
46	}
47	
48	function linkUsuario(u) {
49	  return html`<a class="usuario-link" href="/u/${u.usuario_id ?? u.id}">${avatar(u)}<span><strong>${u.nome}</strong> ${selo(u.papel)}${u.curso ? html`<small>${u.curso}</small>` : ''}</span></a>`;
50	}
51	
52	const erroBox = (erro) => (erro ? html`<p class="alerta">${erro}</p>` : '');
53	
54	const opcoesCurso = (selecionado) =>
55	  config.CURSOS.map((c) => html`<option value="${c}" ${c === selecionado ? 'selected' : ''}>${c}</option>`);
56	
57	// ---------- Layout ----------
58	function layout({ usuario, titulo, ativo, conteudo, avisosNovos = 0 }) {
59	  const item = (chave, href, rotulo, novos = 0) => {
60	    const descricao = novos ? `${rotulo} (${plural(novos, 'aviso novo', 'avisos novos')})` : rotulo;
61	    return html`<a href="${href}" class="${ativo === chave ? 'ativo' : ''}" aria-label="${descricao}"><span class="nav-icone">${icone[chave]}${
62	      novos ? html`<span class="bolinha" aria-hidden="true">${novos > 9 ? '9+' : novos}</span>` : ''
63	    }</span><span>${rotulo}</span></a>`;
64	  };
65	  return html`<!doctype html>
66	<html lang="pt-BR">
67	<head>
68	<meta charset="utf-8">
69	<meta name="viewport" content="width=device-width, initial-scale=1">
70	<title>${titulo ? `${titulo} · ` : ''}${config.NOME_APP}</title>
71	<meta name="theme-color" content="#5b21b6">
72	<link rel="icon" href="/icone.svg" type="image/svg+xml">
73	<link rel="stylesheet" href="/estilo.css">
74	</head>
75	<body>
76	<header class="topo">
77	  <a href="/" class="marca">${config.NOME_APP}</a>
78	  <span class="topo-sub">${config.FACULDADE}</span>
79	  ${usuario?.papel === 'admin' ? html`<a class="topo-link" href="/admin">Administração</a>` : ''}
80	</header>
81	<main class="conteudo">${conteudo}</main>
82	${
83	  usuario
84	    ? html`<nav class="nav-inferior">
85	  ${item('inicio', '/', 'Início')}
86	  ${item('mural', '/mural', 'Mural', avisosNovos)}
87	  ${item('novo', '/novo', 'Postar')}
88	  ${item('ranking', '/ranking', 'Ranking')}
89	  ${item('perfil', `/u/${usuario.id}`, 'Perfil')}
90	</nav>`
91	    : ''
92	}
93	</body>
94	</html>`;
95	}
96	
97	// ---------- Entrar / Cadastrar ----------
98	function caixaBanca(erro) {
99	  return html`<section class="cartao auth banca" id="banca">
100	  <h2>Banca do TCC</h2>
101	  <p class="muted">Entre sem cadastro com o código de acesso da apresentação.</p>
102	  ${erroBox(erro)}
103	  <form method="post" action="/banca" class="form">
104	    <label>Código de acesso<input name="codigo" required autocomplete="off" autocapitalize="none" spellcheck="false"></label>
105	    <span class="banca-rotulo">Entrar como</span>
106	    <div class="banca-perfis">
107	      ${Object.entries(CONTAS_BANCA).map(([perfil, c]) => html`<button class="btn btn-sec" name="perfil" value="${perfil}">${c.rotulo}</button>`)}
108	    </div>
109	  </form>
110	</section>`;
111	}
112	
113	function telaEntrar({ erro, email = '', banca = false, erroBanca }) {
114	  return html`<section class="cartao auth">
115	  <h1 class="marca-grande">${config.NOME_APP}</h1>
116	  <p class="muted">A rede social da ${config.FACULDADE}</p>
117	  ${erroBox(erro)}
118	  <form method="post" action="/entrar" class="form">
119	    <label>E-mail da faculdade<input type="email" name="email" value="${email}" required autocomplete="email"></label>
120	    <label>Senha<input type="password" name="senha" required autocomplete="current-password"></label>
121	    <button class="btn">Entrar</button>
122	  </form>
123	  <p class="muted">Ainda não tem conta? <a href="/cadastrar">Cadastre-se</a></p>
124	</section>
125	${banca ? caixaBanca(erroBanca) : ''}`;
126	}
127	
128	function telaCadastrar({ erro, dados = {} }) {
129	  const dominio = config.DOMINIOS_PERMITIDOS.join(' ou @');
130	  return html`<section class="cartao auth">
131	  <h1 class="marca-grande">${config.NOME_APP}</h1>
132	  <p class="muted">Crie sua conta com o e-mail @${dominio}</p>
133	  ${erroBox(erro)}
134	  <form method="post" action="/cadastrar" class="form">
135	    <label>Nome completo<input name="nome" value="${dados.nome || ''}" required maxlength="60" autocomplete="name"></label>
136	    <label>E-mail da faculdade<input type="email" name="email" value="${dados.email || ''}" required placeholder="voce@${dominio}" autocomplete="email"></label>
137	    <label>Curso<select name="curso" required><option value="">Selecione…</option>${opcoesCurso(dados.curso)}</select></label>
138	    <label>Senha (mínimo 8 caracteres)<input type="password" name="senha" required minlength="8" autocomplete="new-password"></label>
139	    <button class="btn">Criar conta</button>
140	  </form>
141	  <p class="muted">Professores: criem a conta normalmente e peçam à faculdade para liberar o perfil de professor.</p>
142	  <p class="muted">Já tem conta? <a href="/entrar">Entrar</a></p>
143	</section>`;
144	}
145	
146	// ---------- Feed ----------
147	// noFeed = true: mostra os últimos comentários e uma caixa para comentar ali mesmo.
148	function cartaoPost(p, voltar, noFeed = false) {
149	  return html`<article class="post" id="post-${p.id}">
150	  <header class="post-topo">${linkUsuario(p)}<span class="tempo">${tempoRelativo(p.criado_em)}</span></header>
151	  ${
152	    p.imagem
153	      ? html`<a href="/posts/${p.id}"><img class="post-img" src="/uploads/${p.imagem}" alt="Foto publicada por ${p.nome}" loading="lazy"></a>`
154	      : html`<a href="/posts/${p.id}" class="post-texto">${p.legenda}</a>`
155	  }
156	  <div class="post-acoes">
157	    <form method="post" action="/posts/${p.id}/curtir">
158	      <input type="hidden" name="voltar" value="${voltar}">
159	      <button class="btn-icone ${p.curti ? 'curtido' : ''}" aria-label="${p.curti ? 'Descurtir' : 'Curtir'}">${icone.coracao}</button>
160	    </form>
161	    <a class="btn-icone" href="/posts/${p.id}#comentar" aria-label="Comentar">${icone.comentario}</a>
162	  </div>
163	  <div class="post-info">
164	    <strong>${plural(p.n_curtidas, 'curtida', 'curtidas')}</strong>
165	    ${p.imagem && p.legenda ? html`<p class="legenda"><a href="/u/${p.usuario_id}"><strong>${p.nome}</strong></a> ${p.legenda}</p>` : ''}
166	    ${
167	      noFeed
168	        ? comentariosNoFeed(p, voltar)
169	        : p.n_comentarios > 0
170	          ? html`<a class="muted" href="/posts/${p.id}">Ver ${plural(p.n_comentarios, 'comentário', 'comentários')}</a>`
171	          : ''
172	    }
173	  </div>
174	</article>`;
175	}
176	
177	function comentariosNoFeed(p, voltar) {
178	  const ultimos = p.ultimos_comentarios || [];
179	  return html`${
180	    p.n_comentarios > ultimos.length
181	      ? html`<a class="muted" href="/posts/${p.id}">Ver todos os ${p.n_comentarios} comentários</a>`
182	      : ''
183	  }
184	  ${ultimos.map(
185	    (c) => html`<p class="comentario-curto"><a href="/u/${c.usuario_id}"><strong>${c.nome}</strong></a> ${selo(c.papel)} ${c.texto}</p>`,
186	  )}
187	  <form method="post" action="/posts/${p.id}/comentar" class="comentar-feed">
188	    <input type="hidden" name="voltar" value="${voltar}">
189	    <input name="texto" placeholder="Adicione um comentário…" required maxlength="500" aria-label="Comentar no post de ${p.nome}">
190	    <button class="btn-link">Publicar</button>
191	  </form>`;
192	}
193	
194	// Cartão de "fulano ganhou uma medalha" no feed.
195	function cartaoMedalha(m) {
196	  const primeiroNome = m.nome.split(' ')[0];
197	  return html`<article class="post evento evento-medalha" id="medalha-${m.id}">
198	  <header class="post-topo">${linkUsuario(m)}<span class="tempo">${tempoRelativo(m.criado_em)}</span></header>
199	  <div class="evento-corpo">
200	    <span class="evento-emoji" aria-hidden="true">${m.emoji}</span>
201	    <p class="evento-rotulo">🏅 Medalha de professor</p>
202	    <h2>${primeiroNome} ganhou <span class="evento-destaque">${m.medalha}</span></h2>
203	    <p class="muted">entregue por ${
204	      m.professor_id ? html`<a href="/u/${m.professor_id}">${m.professor_nome}</a>` : 'um(a) professor(a)'
205	    } · <span class="pts">+${m.pontos} pts</span></p>
206	    ${m.mensagem ? html`<blockquote>“${m.mensagem}”</blockquote>` : ''}
207	    <a class="btn btn-sec" href="/u/${m.usuario_id}">Ver perfil de ${primeiroNome}</a>
208	  </div>
209	</article>`;
210	}
211	
212	// Cartão de "fulano desbloqueou uma conquista" no feed.
213	function cartaoConquista(c) {
214	  const primeiroNome = c.nome.split(' ')[0];
215	  return html`<article class="post evento evento-conquista" id="conquista-${c.id}">
216	  <header class="post-topo">${linkUsuario(c)}<span class="tempo">${tempoRelativo(c.criado_em)}</span></header>
217	  <div class="evento-corpo">
218	    <span class="evento-emoji" aria-hidden="true">${c.info.emoji}</span>
219	    <p class="evento-rotulo">✨ Nova conquista</p>
220	    <h2>${primeiroNome} desbloqueou <span class="evento-destaque">${c.info.nome}</span></h2>
221	    <p class="muted">${c.info.descricao} · <span class="pts">+${c.info.bonus} pts</span></p>
222	    <a class="btn btn-sec" href="/u/${c.usuario_id}/trofeus">Ver troféus de ${primeiroNome}</a>
223	  </div>
224	</article>`;
225	}
226	
227	function feed({ itens, avisoFixado, pagina, temMais }) {
228	  const voltar = pagina > 1 ? `/?pagina=${pagina}` : '/';
229	  const cartao = {
230	    post: (p) => cartaoPost(p, voltar, true),
231	    medalha: cartaoMedalha,
232	    conquista: cartaoConquista,
233	  };
234	  return html`
235	  ${
236	    avisoFixado
237	      ? html`<a class="aviso-faixa" href="/mural">📢 <strong>${avisoFixado.titulo}</strong><span>Ver no mural ›</span></a>`
238	      : ''
239	  }
240	  ${
241	    itens.length === 0
242	      ? html`<section class="cartao vazio"><p>Nenhum post ainda.</p><a class="btn" href="/novo">Faça o primeiro post</a></section>`
243	      : itens.map((i) => cartao[i.tipo](i.dados))
244	  }
245	  <div class="paginacao">
246	    ${pagina > 1 ? html`<a class="btn btn-sec" href="/?pagina=${pagina - 1}">‹ Mais recentes</a>` : ''}
247	    ${temMais ? html`<a class="btn btn-sec" href="/?pagina=${pagina + 1}">Mais antigos ›</a>` : ''}
248	  </div>`;
249	}
250	
251	function postDetalhe({ post, comentarios, usuario }) {
252	  const podeApagar = (dono) => usuario.id === dono || usuario.papel === 'admin';
253	  return html`${cartaoPost(post, `/posts/${post.id}`)}
254	  ${
255	    podeApagar(post.usuario_id)
256	      ? html`<form method="post" action="/posts/${post.id}/apagar" class="direita" onsubmit="return confirm('Apagar este post?')">
257	          <button class="btn-link perigo">Apagar post</button></form>`
258	      : ''
259	  }
260	  <section class="cartao">
261	    <h2>Comentários</h2>
262	    ${comentarios.length === 0 ? html`<p class="muted">Seja o primeiro a comentar.</p>` : ''}
263	    <ul class="comentarios">
264	      ${comentarios.map(
265	        (c) => html`<li>${avatar(c)}<div><a href="/u/${c.usuario_id}"><strong>${c.nome}</strong></a> ${selo(c.papel)} ${c.texto}
266	          <small class="muted"> · ${tempoRelativo(c.criado_em)}</small>
267	          ${
268	            podeApagar(c.usuario_id)
269	              ? html`<form method="post" action="/comentarios/${c.id}/apagar" class="inline"><button class="btn-link perigo">apagar</button></form>`
270	              : ''
271	          }</div></li>`,
272	      )}
273	    </ul>
274	    <form method="post" action="/posts/${post.id}/comentar" class="form-linha" id="comentar">
275	      <input name="texto" placeholder="Escreva um comentário…" required maxlength="500">
276	      <button class="btn">Enviar</button>
277	    </form>
278	  </section>`;
279	}
280	
281	function novoPost({ erro, legenda = '' }) {
282	  return html`<section class="cartao">
283	  <h1>Novo post</h1>
284	  ${erroBox(erro)}
285	  <form method="post" action="/posts" enctype="multipart/form-data" class="form">
286	    <label>Foto (JPG, PNG, WEBP ou GIF, até ${config.TAMANHO_MAX_IMAGEM_MB} MB)
287	      <input type="file" name="imagem" accept="image/jpeg,image/png,image/webp,image/gif"></label>
288	    <label>Legenda<textarea name="legenda" rows="4" maxlength="2200" placeholder="O que está rolando na ${config.FACULDADE}?">${legenda}</textarea></label>
289	    <button class="btn">Publicar</button>
290	  </form>
291	  <p class="muted">Cada post vale <strong>${PONTOS.post} pontos</strong> para o ranking.</p>
292	</section>`;
293	}
294	
295	// ---------- Perfil ----------
296	function perfil({ perfil: p, stats, medalhas, tiposMedalha, posts, usuario, medalhasDadas, msg }) {
297	  const proprio = usuario.id === p.id;
298	  return html`<section class="cartao perfil">
299	  <div class="perfil-topo">
300	    ${avatar(p, 'g')}
301	    <div>
302	      <h1>${p.nome} ${selo(p.papel)}</h1>
303	      ${p.curso && p.papel !== 'admin' ? html`<p class="muted">${p.curso}</p>` : ''}
304	      ${p.bio ? html`<p class="bio">${p.bio}</p>` : ''}
305	    </div>
306	  </div>
307	  ${msg ? html`<p class="sucesso">${msg}</p>` : ''}
308	  ${
309	    stats
310	      ? html`<div class="numeros">
311	      <div><strong>${fmt(stats.total)}</strong><span>pontos</span></div>
312	      <div><strong>${stats.posicao_geral ?? '–'}º</strong><span>no geral</span></div>
313	      <div><strong>${stats.posicao_curso ?? '–'}º</strong><span>no curso</span></div>
314	      <a href="/u/${p.id}/trofeus"><strong>${stats.medalhas + stats.conquistas.length}</strong><span>prêmios</span></a>
315	    </div>
316	    ${extratoPontos(stats)}`
317	      : ''
318	  }
319	  ${p.papel === 'professor' ? html`<p class="muted">Já entregou ${plural(medalhasDadas, 'medalha', 'medalhas')} para alunos.</p>` : ''}
320	  ${
321	    proprio
322	      ? html`<div class="acoes-perfil">
323	      <a class="btn btn-sec" href="/perfil/editar">Editar perfil</a>
324	      <form method="post" action="/sair"><button class="btn btn-sec">Sair</button></form>
325	    </div>`
326	      : ''
327	  }
328	</section>
329	
330	${
331	  usuario.papel === 'professor' && p.papel === 'aluno'
332	    ? html`<section class="cartao">
333	    <h2>🏅 Dar uma medalha para ${p.nome.split(' ')[0]}</h2>
334	    <form method="post" action="/u/${p.id}/medalha" class="form">
335	      <label>Medalha<select name="tipo_id" required>
336	        ${tiposMedalha.map((t) => html`<option value="${t.id}">${t.emoji} ${t.nome} (+${t.pontos} pts)</option>`)}
337	      </select></label>
338	      <label>Mensagem (opcional)<input name="mensagem" maxlength="200" placeholder="Ex.: Ótima apresentação do trabalho!"></label>
339	      <button class="btn">Entregar medalha</button>
340	    </form>
341	  </section>`
342	    : ''
343	}
344	
345	${stats ? premios({ id: p.id, stats, medalhas, proprio, primeiroNome: p.nome.split(' ')[0] }) : ''}
346	
347	<section class="cartao">
348	  <h2>Posts <span class="contador">${posts.length}</span></h2>
349	  ${
350	    posts.length === 0
351	      ? html`<p class="muted">${proprio ? 'Você ainda não publicou nada.' : 'Nenhum post ainda.'}</p>
352	        ${proprio ? html`<a class="btn" href="/novo">Publicar o primeiro post</a>` : ''}`
353	      : html`<div class="grade">
354	    ${posts.map(
355	      (post) => html`<a href="/posts/${post.id}" class="grade-item" aria-label="Ver post">${
356	        post.imagem
357	          ? html`<img src="/uploads/${post.imagem}" alt="${post.legenda || `Foto de ${p.nome}`}" loading="lazy">`
358	          : html`<span>${post.legenda.slice(0, 80)}</span>`
359	      }</a>`,
360	    )}
361	  </div>`
362	  }
363	</section>`;
364	}
365	
366	// De onde vieram os pontos do aluno (abre ao tocar).
367	function extratoPontos(s) {
368	  const linhas = [
369	    [plural(s.posts, 'post publicado', 'posts publicados'), s.posts * PONTOS.post],
370	    [plural(s.curtidas, 'curtida recebida', 'curtidas recebidas'), s.curtidas * PONTOS.curtida],
371	    [plural(s.comentarios, 'post de colega comentado', 'posts de colegas comentados'), s.comentarios * PONTOS.comentario],
372	    [plural(s.medalhas, 'medalha de professor', 'medalhas de professores'), s.pontos_medalhas],
373	    [plural(s.conquistas.length, 'conquista', 'conquistas'), s.pontos_conquistas],
374	  ];
375	  return html`<details class="extrato">
376	  <summary>De onde vêm os pontos</summary>
377	  <table>
378	    ${linhas.map(([rotulo, pts]) => html`<tr><td>${rotulo}</td><td class="pts">+${fmt(pts)}</td></tr>`)}
379	    <tr class="total"><td>Total</td><td>${fmt(s.total)} pts</td></tr>
380	  </table>
381	</details>`;
382	}
383	
384	// Prêmios: medalhas dadas por professores + conquistas desbloqueadas.
385	function premios({ id, stats, medalhas, proprio, primeiroNome }) {
386	  const ganhas = CONQUISTAS.filter((c) => stats.conquistas.some((x) => x.id === c.id));
387	  const faltam = CONQUISTAS.length - ganhas.length;
388	  const total = medalhas.length + ganhas.length;
389	  return html`<section class="cartao" id="premios">
