62	    hashToken(token),
63	    usuarioId,
64	    Date.now() + DURACAO_SESSAO_MS,
65	  );
66	  res.cookie(COOKIE, token, {
67	    httpOnly: true,
68	    sameSite: 'lax',
69	    secure: process.env.NODE_ENV === 'production',
70	    maxAge: DURACAO_SESSAO_MS,
