  // Ex.: CODIGO_BANCA=maxx2026 npm start
  CODIGO_BANCA: process.env.CODIGO_BANCA || '',

  PORTA: Number(process.env.PORT) || 3000,
  PASTA_DADOS: process.env.MAXX_DADOS || path.join(__dirname, '..', 'dados'),
  TAMANHO_MAX_IMAGEM_MB: 5,
};

