298	  position: absolute; top: -4px; right: -9px;
299	  min-width: 18px; height: 18px; padding: 0 4px; border-radius: 99px;
300	  background: var(--primaria-2); color: #fff; border: 2px solid var(--cartao);
301	  font-size: .62rem; font-weight: 800; line-height: 14px; text-align: center;
302	}
303	.texto-aviso { white-space: pre-wrap; overflow-wrap: anywhere; }
304	
305	/* ---------- Admin ---------- */
306	.lista-admin { list-style: none; padding: 0; margin: 1rem 0 0; display: grid; gap: .6rem; }
307	.lista-admin li { display: flex; align-items: center; justify-content: space-between; gap: .6rem; flex-wrap: wrap; padding-bottom: .6rem; border-bottom: 1px solid var(--borda); }
308	
309	/* ---------- Troféus ---------- */
310	.numeros a { display: grid; color: var(--texto); border-radius: 10px; }
311	.numeros a:hover { text-decoration: none; background: var(--primaria-suave); }
312	.numeros a span { color: var(--primaria); }
313	.numeros-3 { grid-template-columns: repeat(3, 1fr); }
314	.btn-largo { display: block; margin-top: 1rem; }
315	.voltar { font-size: .85rem; display: inline-block; margin-bottom: .5rem; }
316	.trofeus-topo { text-align: center; }
317	.placar { margin: 0 0 .5rem; color: var(--muted); }
318	.placar strong { font-size: 2rem; color: var(--texto); }
319	
320	.barra { height: 8px; border-radius: 99px; background: var(--borda); overflow: hidden; width: 100%; }
321	.barra span { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--primaria), var(--primaria-2)); }
322	
323	.proxima { border-color: var(--primaria); }
324	.proxima .evento-rotulo { margin: 0 0 .6rem; }
325	.proxima-corpo { display: flex; gap: .9rem; align-items: center; }
326	.proxima-corpo > div { display: grid; gap: .3rem; flex: 1; min-width: 0; }
327	.proxima .trofeu-emoji { font-size: 2.8rem; }
328	.proxima.completo p { margin: 0; text-align: center; font-weight: 700; }
329	
330	.trofeus { list-style: none; padding: 0; margin: .8rem 0 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: .6rem; }
331	.trofeu { position: relative; display: grid; justify-items: center; align-content: start; text-align: center; gap: .3rem; padding: .9rem .6rem; border-radius: 14px; border: 1px solid var(--borda); }
332	.trofeu small { color: var(--muted); font-size: .75rem; }
333	.trofeu .pts { font-size: .75rem; }
334	.trofeu-emoji { font-size: 2.2rem; line-height: 1; }
335	.trofeu-status { font-size: .72rem; font-weight: 600; color: var(--muted); }
336	.trofeu .barra { height: 6px; margin-top: .2rem; }
337	.trofeu.ganhou { background: var(--primaria-suave); border-color: var(--primaria); }
338	.trofeu.ganhou .trofeu-emoji { filter: drop-shadow(0 3px 6px rgb(0 0 0 / .2)); }
339	.trofeu.ganhou .trofeu-status { color: var(--sucesso); }
340	.trofeu.ouro { background: #fef3c7; border-color: var(--ouro); }
341	.trofeu.bloqueada { border-style: dashed; }
342	.trofeu.bloqueada .trofeu-emoji { filter: grayscale(1); opacity: .4; }
343	.trofeu.bloqueada strong { color: var(--muted); }
344	.trofeu-vezes { position: absolute; top: .4rem; right: .5rem; font-size: .75rem; font-weight: 800; background: var(--ouro); color: #fff; border-radius: 99px; padding: .05rem .45rem; }
345	@media (prefers-color-scheme: dark) {
346	  .trofeu.ouro { background: #3b2a0a; }
347	}
