file.content:
:root {
  --fundo: #f4f2f8;
  --cartao: #ffffff;
  --texto: #1c1830;
  --muted: #6b6680;
  --borda: #e4e0ee;
  --primaria: #5b21b6;
  --primaria-2: #db2777;
  --primaria-suave: #ede9fe;
  --perigo: #dc2626;
  --sucesso: #15803d;
  --ouro: #f59e0b;
  --raio: 16px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  color-scheme: light;
}

@media (prefers-color-scheme: dark) {
  :root {
    --fundo: #0f0d17;
    --cartao: #1a1726;
    --texto: #f1eff8;
    --muted: #a19bb8;
    --borda: #2d2840;
    --primaria: #a78bfa;
    --primaria-2: #f472b6;
    --primaria-suave: #2a2142;
    --perigo: #f87171;
    --sucesso: #4ade80;
    color-scheme: dark;
  }
}

* { box-sizing: border-box; }
body { margin: 0; background: var(--fundo); color: var(--texto); line-height: 1.45; }
a { color: var(--primaria); text-decoration: none; }
a:hover { text-decoration: underline; }
h1, h2, h3 { margin: 0 0 .6rem; line-height: 1.2; }
h1 { font-size: 1.35rem; }
h2 { font-size: 1.1rem; }
h3 { font-size: 1rem; margin-top: 1rem; }
img { max-width: 100%; display: block; }

/* ---------- Topo e navegação ---------- */
.topo {
  position: sticky; top: 0; z-index: 10;
  display: flex; align-items: baseline; gap: .5rem;
  padding: .7rem 1rem; background: var(--cartao); border-bottom: 1px solid var(--borda);
}
.marca, .marca-grande {
  font-weight: 800; letter-spacing: -.02em;
  background: linear-gradient(90deg, var(--primaria), var(--primaria-2));
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.marca { font-size: 1.5rem; }
.marca:hover { text-decoration: none; }
.marca-grande { font-size: 2.6rem; text-align: center; margin: 0; }
.topo-sub { color: var(--muted); font-size: .85rem; }
.topo-link { margin-left: auto; font-size: .9rem; font-weight: 600; }

.conteudo { max-width: 560px; margin: 0 auto; padding: 1rem 1rem 6rem; display: grid; gap: 1rem; }

.nav-inferior {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 10;
  display: flex; justify-content: space-around;
  background: var(--cartao); border-top: 1px solid var(--borda);
  padding: .4rem 0 calc(.4rem + env(safe-area-inset-bottom));
}
.nav-inferior a { display: flex; flex-direction: column; align-items: center; color: var(--muted); font-size: .7rem; padding: .2rem .6rem; }
.nav-inferior a:hover { text-decoration: none; color: var(--texto); }
.nav-inferior a.ativo { color: var(--primaria); }

/* ---------- Componentes ---------- */
.cartao { background: var(--cartao); border: 1px solid var(--borda); border-radius: var(--raio); padding: 1.1rem; min-width: 0; }
.muted { color: var(--muted); font-size: .9rem; }
.direita { text-align: right; }
.vazio { text-align: center; display: grid; gap: .6rem; justify-items: center; }

.btn {
  display: inline-block; border: 0; border-radius: 10px; padding: .65rem 1.1rem; cursor: pointer;
  font: inherit; font-weight: 600; color: #fff; text-align: center;
  background: linear-gradient(90deg, #5b21b6, #db2777);
}
.btn:hover { filter: brightness(1.08); text-decoration: none; }
.btn-sec { background: var(--primaria-suave); color: var(--primaria); }
.btn-link { background: none; border: 0; padding: 0; cursor: pointer; font: inherit; color: var(--primaria); font-size: .85rem; }
.perigo { color: var(--perigo); }
.btn-icone { background: none; border: 0; padding: .25rem; cursor: pointer; color: var(--texto); display: inline-flex; }
.btn-icone.curtido { color: #e11d48; }
.btn-icone.curtido svg { fill: currentColor; }

.form { display: grid; gap: .8rem; }
.form label { display: grid; gap: .3rem; font-size: .9rem; font-weight: 600; }
.form label.check { display: flex; align-items: center; gap: .5rem; font-weight: 400; }
input, select, textarea {
  font: inherit; color: var(--texto); background: var(--fundo);
  border: 1px solid var(--borda); border-radius: 10px; padding: .6rem .7rem; width: 100%;
}
input[type=checkbox] { width: auto; }
input:focus, select:focus, textarea:focus { outline: 2px solid var(--primaria); outline-offset: 1px; }
.form-linha { display: flex; gap: .5rem; align-items: center; }
.form-linha input { flex: 1; }
.form-linha select { width: auto; }
.inline { display: inline; }

.alerta { background: #fee2e2; color: #991b1b; padding: .6rem .8rem; border-radius: 10px; margin: 0 0 .8rem; }
.sucesso { background: #dcfce7; color: #166534; padding: .6rem .8rem; border-radius: 10px; }

.auth { margin-top: 2rem; display: grid; gap: .8rem; }
.auth p { text-align: center; margin: 0; }
.banca { margin-top: 1rem; border-style: dashed; }
.banca h2 { margin: 0; text-align: center; font-size: 1.1rem; }
.banca-rotulo { font-size: .9rem; font-weight: 600; }
.banca-perfis { display: grid; grid-template-columns: repeat(auto-fit, minmax(110px, 1fr)); gap: .5rem; }

.avatar { border-radius: 50%; object-fit: cover; flex-shrink: 0; }
.avatar-p { width: 36px; height: 36px; }
.avatar-g { width: 84px; height: 84px; font-size: 2rem; }
.avatar-letra {
  display: inline-grid; place-items: center; font-weight: 700; color: #fff;
  background: linear-gradient(135deg, hsl(var(--matiz) 70% 55%), hsl(calc(var(--matiz) + 40) 70% 45%));
}

.usuario-link { display: flex; align-items: center; gap: .6rem; color: var(--texto); min-width: 0; }
.usuario-link:hover { text-decoration: none; }
.usuario-link > span { display: grid; min-width: 0; }
.usuario-link small { color: var(--muted); font-size: .78rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.selo { display: inline-block; font-size: .68rem; font-weight: 700; padding: .1rem .45rem; border-radius: 99px; vertical-align: middle; }
.selo-prof { background: #fef3c7; color: #92400e; }
.selo-oficial { background: var(--primaria-suave); color: var(--primaria); }

/* ---------- Posts ---------- */
.post { background: var(--cartao); border: 1px solid var(--borda); border-radius: var(--raio); overflow: hidden; }
.post-topo { display: flex; align-items: center; justify-content: space-between; gap: .5rem; padding: .7rem .9rem; }
.tempo { color: var(--muted); font-size: .8rem; white-space: nowrap; }
.post-img { width: 100%; max-height: 640px; object-fit: cover; background: var(--fundo); }
.post-texto {
  display: block; padding: 2rem 1.4rem; font-size: 1.15rem; color: var(--texto); white-space: pre-wrap; overflow-wrap: anywhere;
  background: linear-gradient(135deg, var(--primaria-suave), var(--fundo));
}
.post-texto:hover { text-decoration: none; }
.post-acoes { display: flex; gap: .3rem; padding: .4rem .6rem 0; }
.post-acoes form { margin: 0; }
.post-info { padding: .2rem .9rem .9rem; display: grid; gap: .25rem; }
.legenda { margin: 0; white-space: pre-wrap; overflow-wrap: anywhere; }
.legenda a { color: var(--texto); }

.aviso-faixa {
  display: flex; gap: .5rem; align-items: center; padding: .8rem 1rem; border-radius: var(--raio);
  background: linear-gradient(90deg, #5b21b6, #db2777); color: #fff;
}
.aviso-faixa:hover { text-decoration: none; filter: brightness(1.08); }
.aviso-faixa span { margin-left: auto; font-size: .85rem; white-space: nowrap; }

.comentarios { list-style: none; padding: 0; margin: 0 0 1rem; display: grid; gap: .8rem; }
.comentarios li { display: flex; gap: .6rem; overflow-wrap: anywhere; }
.comentarios a { color: var(--texto); }

/* Comentários direto no feed */
.comentario-curto { margin: 0; overflow-wrap: anywhere; }
.comentario-curto a { color: var(--texto); }
.comentar-feed { display: flex; gap: .5rem; align-items: center; margin-top: .35rem; border-top: 1px solid var(--borda); padding-top: .5rem; }
.comentar-feed input { flex: 1; border: 0; background: none; padding: .35rem 0; }
.comentar-feed input:focus { outline: none; }
.comentar-feed .btn-link { font-weight: 700; }

/* Medalhas e conquistas no feed */
.evento-corpo {
  display: grid; justify-items: center; text-align: center; gap: .35rem; padding: 1.4rem 1.2rem 1.3rem;
  background: radial-gradient(circle at 50% 0%, var(--primaria-suave), transparent 70%);
}
.evento-medalha .evento-corpo { background: radial-gradient(circle at 50% 0%, #fef3c7, transparent 70%); }
.evento-emoji { font-size: 3.4rem; line-height: 1; filter: drop-shadow(0 4px 8px rgb(0 0 0 / .15)); }
.evento-rotulo { margin: .2rem 0 0; font-size: .75rem; font-weight: 700; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }
.evento-corpo h2 { margin: 0; font-size: 1.15rem; }
.evento-destaque { color: var(--primaria); }
.evento-corpo p { margin: 0; }
.evento-corpo blockquote { margin: .3rem 0; font-style: italic; max-width: 32ch; overflow-wrap: anywhere; }
.evento-corpo .btn { margin-top: .5rem; font-size: .9rem; padding: .5rem 1rem; }
@media (prefers-color-scheme: dark) {
  .evento-medalha .evento-corpo { background: radial-gradient(circle at 50% 0%, #3b2a0a, transparent 70%); }
}

.paginacao { display: flex; justify-content: space-between; gap: .5rem; }

/* ---------- Perfil ---------- */
.perfil-topo { display: flex; align-items: center; gap: 1rem; }
.perfil-topo h1 { margin-bottom: .2rem; }
.bio { margin: .3rem 0 0; white-space: pre-wrap; }
.numeros { display: grid; grid-template-columns: repeat(4, 1fr); text-align: center; margin-top: 1rem; gap: .3rem; }
.numeros div { display: grid; }
.numeros strong { font-size: 1.25rem; }
.numeros span { font-size: .75rem; color: var(--muted); }
.acoes-perfil { display: flex; gap: .5rem; margin-top: 1rem; flex-wrap: wrap; }
.acoes-perfil form { margin: 0; }
.contador { font-size: .8rem; font-weight: 600; color: var(--muted); background: var(--primaria-suave); border-radius: 999px; padding: .05rem .5rem; vertical-align: middle; }
.cartao h3 { font-size: .9rem; color: var(--muted); margin: 1rem 0 .5rem; }
.cartao h2 + h3 { margin-top: 0; }
details > summary { cursor: pointer; color: var(--primaria); font-size: .9rem; }
.extrato { margin-top: .8rem; text-align: center; }
.extrato table { width: 100%; max-width: 360px; margin: .6rem auto 0; border-collapse: collapse; font-size: .9rem; text-align: left; }
.extrato td { padding: .3rem 0; border-bottom: 1px solid var(--borda); }
.extrato td:last-child { text-align: right; white-space: nowrap; }
.extrato .total td { border-bottom: 0; font-weight: 700; }

.conquistas { list-style: none; padding: 0; margin: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: .6rem; }
.conquistas li { display: grid; justify-items: center; text-align: center; gap: .15rem; padding: .7rem .4rem; border-radius: 12px; border: 1px solid var(--borda); }
.conquistas .emoji { font-size: 1.8rem; }
.conquistas small { color: var(--muted); font-size: .72rem; }
.conquistas .pts { font-size: .75rem; }
.conquistas .ganhou { background: var(--primaria-suave); border-color: var(--primaria); }

.medalhas { list-style: none; padding: 0; margin: 0; display: grid; gap: .8rem; }
.medalhas li { display: flex; gap: .7rem; }
.medalhas .emoji { font-size: 2rem; }
.medalhas small { display: block; }
.medalhas p { margin: .2rem 0 0; font-style: italic; }
.pts { color: var(--sucesso); font-weight: 700; font-size: .85rem; }

.grade { display: grid; grid-template-columns: repeat(3, 1fr); gap: 3px; }
.grade-item { aspect-ratio: 1; overflow: hidden; background: var(--primaria-suave); display: grid; place-items: center; border-radius: 4px; }
.grade-item img { width: 100%; height: 100%; object-fit: cover; }
.grade-item span { padding: .4rem; font-size: .75rem; color: var(--texto); text-align: center; overflow-wrap: anywhere; }

/* ---------- Ranking ---------- */
.abas {
  display: flex; gap: .4rem; overflow-x: auto; margin: .8rem -1.1rem 0; padding: 0 1.1rem .3rem;
  scrollbar-width: thin; -webkit-overflow-scrolling: touch;
}
.aba {
  flex-shrink: 0; white-space: nowrap; padding: .4rem .8rem; border-radius: 999px;
  border: 1px solid var(--borda); color: var(--texto); font-size: .85rem; font-weight: 600;
}
.aba:hover { text-decoration: none; background: var(--primaria-suave); }
.aba small { color: var(--muted); font-weight: 400; margin-left: .15rem; }
.aba.ativa { background: var(--primaria); border-color: var(--primaria); color: var(--cartao); }
.aba.ativa small { color: inherit; opacity: .8; }
.sua-frase { margin: .8rem 0 0; padding: .6rem .8rem; border-radius: 12px; background: var(--primaria-suave); font-size: .92rem; }

.avatar-m { width: 56px; height: 56px; font-size: 1.4rem; }
.podio {
  list-style: none; padding: 0; margin: .5rem 0 1rem;
  display: grid; grid-template-columns: repeat(3, 1fr); align-items: end; gap: .5rem;
}
.podio li { display: grid; justify-items: center; gap: .4rem; min-width: 0; }
.podio a { display: grid; justify-items: center; gap: .15rem; color: var(--texto); text-align: center; min-width: 0; max-width: 100%; }
.podio a:hover { text-decoration: none; }
.podio strong { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 100%; }
.podio small { color: var(--muted); font-weight: 700; }
.podio .degrau {
  width: 100%; display: grid; place-items: start center; padding-top: .4rem; font-size: 1.6rem;
  border-radius: 12px 12px 4px 4px; background: var(--primaria-suave);
}
.podio-1 { order: 2; } .podio-1 .degrau { height: 5.5rem; background: linear-gradient(var(--ouro), transparent); }
.podio-2 { order: 1; } .podio-2 .degrau { height: 4rem; }
.podio-3 { order: 3; } .podio-3 .degrau { height: 3rem; }
.podio li.eu strong { color: var(--primaria); }
.podio-1 .avatar { box-shadow: 0 0 0 3px var(--ouro); }

.ranking { list-style: none; padding: 0; margin: 0; display: grid; gap: .3rem; }
.ranking li.zerado { opacity: .6; }

.lideres { list-style: none; padding: 0; margin: 0; display: grid; gap: .3rem; }
.lider-curso { display: flex; align-items: center; gap: .6rem; padding: .5rem .6rem; border-radius: 12px; color: var(--texto); }
.lider-curso:hover { text-decoration: none; background: var(--primaria-suave); }
.lider-curso > span:first-child { flex: 1; display: grid; min-width: 0; }
.lider-curso small { color: var(--muted); font-size: .78rem; }
.lider-nome { font-weight: 600; text-align: right; }
.lider-nome small { display: block; }
.seta { color: var(--muted); font-size: 1.3rem; }
.ranking li { display: flex; align-items: center; gap: .7rem; padding: .5rem .6rem; border-radius: 12px; }
.ranking li.eu { background: var(--primaria-suave); }
.ranking .pos { width: 2.2rem; text-align: center; font-weight: 700; font-size: 1.1rem; flex-shrink: 0; }
.ranking .usuario-link { flex: 1; }
.ranking .total { font-weight: 800; white-space: nowrap; }
.ranking .total small { font-weight: 400; color: var(--muted); }

.regras { list-style: none; padding: 0; margin: 0; display: grid; gap: .4rem; }
.regras li { display: flex; justify-content: space-between; gap: 1rem; font-size: .9rem; border-bottom: 1px dashed var(--borda); padding-bottom: .4rem; }
.regras strong { color: var(--sucesso); white-space: nowrap; }

/* ---------- Mural ---------- */
.aviso.fixado { border-color: var(--primaria); }
.aviso.novo { box-shadow: inset 4px 0 0 var(--primaria-2); }
.aviso h2 { margin: .7rem 0 .3rem; }
.aviso-topo { display: flex; align-items: center; justify-content: space-between; gap: .6rem; }
.aviso-selos { display: flex; gap: .3rem; flex-shrink: 0; }
.selo-novo { background: var(--primaria-2); color: #fff; }
.destaque-novo { color: var(--primaria-2); }
.novo-aviso { margin-top: .6rem; }
.novo-aviso .form { margin-top: .8rem; }
.dica { margin: 0; font-size: .8rem; }

/* Bolinha de avisos novos no menu */
.nav-icone { position: relative; display: inline-flex; }
.bolinha {
  position: absolute; top: -4px; right: -9px;
  min-width: 18px; height: 18px; padding: 0 4px; border-radius: 99px;
  background: var(--primaria-2); color: #fff; border: 2px solid var(--cartao);
  font-size: .62rem; font-weight: 800; line-height: 14px; text-align: center;
}
.texto-aviso { white-space: pre-wrap; overflow-wrap: anywhere; }

/* ---------- Admin ---------- */
.lista-admin { list-style: none; padding: 0; margin: 1rem 0 0; display: grid; gap: .6rem; }
.lista-admin li { display: flex; align-items: center; justify-content: space-between; gap: .6rem; flex-wrap: wrap; padding-bottom: .6rem; border-bottom: 1px solid var(--borda); }

/* ---------- Troféus ---------- */
.numeros a { display: grid; color: var(--texto); border-radius: 10px; }
.numeros a:hover { text-decoration: none; background: var(--primaria-suave); }
.numeros a span { color: var(--primaria); }
.numeros-3 { grid-template-columns: repeat(3, 1fr); }
.btn-largo { display: block; margin-top: 1rem; }
.voltar { font-size: .85rem; display: inline-block; margin-bottom: .5rem; }
.trofeus-topo { text-align: center; }
.placar { margin: 0 0 .5rem; color: var(--muted); }
.placar strong { font-size: 2rem; color: var(--texto); }

.barra { height: 8px; border-radius: 99px; background: var(--borda); overflow: hidden; width: 100%; }
.barra span { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--primaria), var(--primaria-2)); }

.proxima { border-color: var(--primaria); }
.proxima .evento-rotulo { margin: 0 0 .6rem; }
.proxima-corpo { display: flex; gap: .9rem; align-items: center; }
